         (PP SEQE BS P END BUF lo slo : Z) (bs : list byte) (sev tg0 pad : word) (len0 q0 : Z),
  HM segs R HIA h LB LF m -> (length LF < 512)%nat ->                                                (* [comment removed for export] *)
  rw_cells segs m PP [C8 (Z_to_bv 64 P)] -> rw_cells segs m SEQE [C8 sev] ->
  rw_cells segs m BS (buf_cells tg0 pad len0 q0) -> bytes_at segs m BUF bs ->
  BUF <= P -> P <= END -> END <= BUF + Z.of_nat (length bs) -> BUF + Z.of_nat (length bs) < 2^63 ->
  (PP + 8 <= SEQE \/ SEQE + 8 <= PP) -> (PP + 8 <= BS \/ BS + 24 <= PP) -> (SEQE + 8 <= BS \/ BS + 24 <= SEQE) ->
  (Z.of_nat (length bs) = 0 \/ PP + 8 <= BUF \/ BUF + Z.of_nat (length bs) <= PP) ->
  (Z.of_nat (length bs) = 0 \/ SEQE + 8 <= BUF \/ BUF + Z.of_nat (length bs) <= SEQE) ->
  (Z.of_nat (length bs) = 0 \/ BS + 24 <= BUF \/ BUF + Z.of_nat (length bs) <= BS) ->
  PP mod 8 = 0 -> SEQE mod 8 = 0 -> BS mod 8 = 0 ->
  0 < PP /\ PP + 8 <= 2^64 -> 0 < SEQE /\ SEQE + 8 <= 2^64 -> 0 < BS /\ BS + 24 <= 2^64 -> 0 < BUF ->
  (* [comment removed for export] *)
  stk segs m lo (bv_unsigned sp) -> sshad segs (arl_AL R) m slo (bv_unsigned sp) ->
  lo <= bv_unsigned sp - PKCS7_CINFO_STACK_A -> lo <= bv_unsigned sp - 144 - arl_need_smalloc R -> 0 <= arl_need_smalloc R ->
  arl_stklo R <= slo -> slo <= lo ->
  bv_unsigned sp mod 16 = 0 -> bv_unsigned sp <= htop segs R HIA h -> bv_unsigned sp <= 2^47 ->
  (PP + 8 <= lo \/ bv_unsigned sp <= PP) -> (SEQE + 8 <= lo \/ bv_unsigned sp <= SEQE) -> (BS + 24 <= lo \/ bv_unsigned sp <= BS) ->
  (Z.of_nat (length bs) = 0 \/ BUF + Z.of_nat (length bs) <= lo \/ bv_unsigned sp <= BUF) ->
  (* [comment removed for export] *)
  client_range (arl_L R) (LB ++ fdata LF) lo PP 8 -> client_range (arl_L R) (LB ++ fdata LF) lo SEQE 8 ->
  client_range (arl_L R) (LB ++ fdata LF) lo BS 24 -> client_range (arl_L R) (LB ++ fdata LF) lo BUF (Z.of_nat (length bs)) ->
  client_wrange (arl_L R) (LB ++ fdata LF) lo (htop segs R HIA h) PP 8 ->
  client_wrange (arl_L R) (LB ++ fdata LF) lo (htop segs R HIA h) SEQE 8 ->
  client_wrange (arl_L R) (LB ++ fdata LF) lo (htop segs R HIA h) BS 24 ->
  mem_inv segs m -> tp = Z_to_bv 64 (arl_tp R) ->
  (* [comment removed for export] *)
  aobj segs (arl_AL R) (hcs segs R HIA h) m PP 8 -> aobj segs (arl_AL R) (hcs segs R HIA h) m SEQE 8 ->
  aobj segs (arl_AL R) (hcs segs R HIA h) m BS 24 -> aobj segs (arl_AL R) (hcs segs R HIA h) m BUF (Z.of_nat (length bs)) ->
  a0 = Z_to_bv 64 PP -> a1 = Z_to_bv 64 END -> a2 = Z_to_bv 64 SEQE -> a3 = Z_to_bv 64 BS ->
  evtA segs (arl_AL R) (hcs segs R HIA h)
       (pkcs7_cinfo_postA segs R HIA h LB LF ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc PP SEQE BS P END lo slo pad m)
